def compute(vars):
    q2_value = vars["v1"]
    q3_value = vars["v2"]
    change = q3_value - q2_value
    return {
        "value": change,
        "trace": {
            "q2_value": q2_value,
            "q3_value": q3_value,
            "difference": change,
            "output_meta": {
                "currency": "$",
                "scale": None,
                "unit": "per share"
            }
        }
    }
